    function getPlanForWeek(weekKey) {
      if (typeof datasets === 'undefined' || !datasets) return null;
      if (datasets[weekKey]) return datasets[weekKey];
      for (const k in datasets) {
        if (k.startsWith(weekKey) || (weekKey && weekKey.startsWith(k.split(' (')[0]))) {
          return datasets[k];
        }
      }
      return datasets["Semana 35 (23 al 29 de Agosto de 2026)"] || Object.values(datasets)[0] || null;
    }

    function renderDateBar() {
      try {
        const plan = getPlanForWeek(activeWeek);
        const bar = document.getElementById('date-bar');
        if (!bar) return;
        bar.innerHTML = '';
        bar.className = 'flex items-center gap-2 overflow-x-auto pb-3 mb-6 w-full';

        if (!plan || !plan.days) return;

        plan.days.forEach((day, idx) => {
          const btn = document.createElement('button');
          const isActive = idx === selectedIdx;
          const todayNumStr = new Date().getDate().toString();
          const isToday = (day.day_num === todayNumStr || (day.day_num && parseInt(day.day_num) === new Date().getDate()) || (day.date_str && day.date_str.includes(todayNumStr)));
          
          btn.type = 'button';
          btn.className = `min-h-[48px] px-4 py-2.5 rounded-xl border text-xs font-brand-body flex items-center gap-2 transition-all cursor-pointer whitespace-nowrap ${
            isActive 
              ? 'bg-[#3AAA35] text-white shadow-md border-[#3AAA35] font-bold' 
              : 'bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-300 border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-700'
          }`;
          
          const todayTag = isToday ? '<span class="text-[10px] uppercase font-bold text-[#FFCC00] bg-slate-900 px-1.5 py-0.5 rounded ml-1">HOY</span>' : '';
          
          let dayNumText = (day.day_num || (day.date_str ? day.date_str.split(' ')[0] : (idx + 1))).toString().trim().replace(/[\s\-_]+$/, '');
          let dayShortText = (day.day || '').substring(0, 3).toUpperCase().trim().replace(/[\s\-_]+$/, '');

          btn.innerHTML = `<span class="font-bold text-sm font-brand-title">${dayNumText}</span> <span class="font-semibold">${dayShortText}</span>${todayTag ? ' ' + todayTag : ''}`;
          
          btn.onclick = () => {
            selectedIdx = idx;
            renderDateBar();
            renderDay(idx);
          };
          bar.appendChild(btn);
        });
      } catch (e) {
        console.error("Error en renderDateBar:", e);
      }
    }

    let currentTab = 'menu';

    function switchTab(tabId, btn) {
      try {
        const map = {
          'design': 'v-menu',
          'menu': 'v-menu',
          'recipes': 'v-prep',
          'prep': 'v-prep',
          'supply': 'v-shop',
          'shop': 'v-shop',
          'metrics': 'v-nutri',
          'nutri': 'v-nutri'
        };
        const targetId = map[tabId] || (tabId && tabId.startsWith('v-') ? tabId : 'v-menu');
        currentTab = targetId.replace('v-', '');

        document.querySelectorAll('.v-panel').forEach(el => el.style.display = 'none');
        const target = document.getElementById(targetId);
        if (target) target.style.display = 'block';

        document.querySelectorAll('.tab-btn').forEach(b => {
          b.classList.remove('bg-[#1C75BC]', 'text-white', 'border-[#1C75BC]');
          b.classList.add('bg-slate-100', 'dark:bg-slate-800', 'text-slate-700', 'dark:text-slate-300', 'border-slate-200', 'dark:border-slate-700');
        });

        const activeBtn = btn || document.getElementById(`tab-btn-${tabId}`);
        if (activeBtn) {
          activeBtn.classList.remove('bg-slate-100', 'dark:bg-slate-800', 'text-slate-700', 'dark:text-slate-300', 'border-slate-200', 'dark:border-slate-700');
          activeBtn.classList.add('bg-[#1C75BC]', 'text-white', 'border-[#1C75BC]');
        }

        if (typeof updateExportButtonUI === 'function') updateExportButtonUI();
      } catch (e) {
        console.error("Error en switchTab:", e);
      }
    }

    function switchView(vId, btn) {
      switchTab(vId, btn);
    }

/**
 * Atelier T.I.L.O.® — Componente de Recetas 100% Pasivo SSOT (V15.22.1)
 * Renderizado Pasivo de Datos Estructurados sin Parsers Regex ni Plantillas Estáticas.
 * Escalamiento Unitario Estricto por Persona: (base_qty_per_person * activeDiners)
 */

function sanitizeDishTitle(title) {
  if (!title) return "";
  return title
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/\(.*?\)/g, "")
    .trim();
}

function normalizeQuantity(qty, unit) {
  const num = parseFloat(qty);
  if (isNaN(num)) return qty;

  const u = (unit || "").toLowerCase();
  if (u.includes("piez") || u.includes("huevo") || u.includes("unidad") || u.includes("hoja")) {
    return Math.ceil(num).toString();
  }
  const rounded = Math.round(num * 10) / 10;
  return rounded.toString();
}

function stripAccents(str) {
  if (!str) return "";
  return str.normalize("NFD").replace(/[̀-ͯ]/g, "");
}

const INGREDIENT_CANONICAL_MAP_JS = {
  "aceite-oliva": ["aceite de oliva", "aceite de oliva extra virgen", "aceite vevo", "aceite de oliva extra virgen vevo", "aceite de oliva virgen extra"],
  "te-verde": ["té verde", "te verde", "té verde orgánico", "matcha"],
  "huevo-organico": ["huevo", "huevos", "huevos frescos", "huevos orgánicos", "huevos frescos orgánicos", "huevos frescos orgánicos de pastoreo", "huevos enteros"],
  "pechuga-pavo": ["pechuga de pavo", "pavo artesanal", "pechuga de pavo artesanal", "jamón de pavo", "tocino de pavo"],
  "pechuga-pollo": ["pechuga de pollo", "pollo fresco", "pechuga de pollo fresca", "muslos de pollo"],
  "sirloin-magro": ["carne molida de sirloin", "sirloin magro", "carne molida de sirloin magra"],
  "filete-res": ["filete de res", "filete de res magro", "ribeye", "sirloin", "medallones de mignon"],
  "huachinango-fresco": ["huachinango", "filete de huachinango", "filete de huachinango fresco", "filete de huachinango al horno"],
  "robalo-fresco": ["róbalo", "robalo", "filete de róbalo", "filete de robalo fresco", "filete de róbalo a la plancha"],
  "salmon-salvaje": ["salmón", "salmon", "salmón salvaje", "filete de salmón fresco", "filete de salmón salvaje", "filete de salmón fresco con piel"],
  "pescado-blanco": ["pescado blanco", "filete de pescado blanco", "filete de pescado blanco fresco"],
  "atun-fresco": ["atún", "atun", "filete de atún fresco"],
  "queso-parmesano": ["queso parmesano", "parmesano maduro", "queso parmesano maduro"],
  "queso-manchego": ["queso manchego", "manchego maduro", "queso manchego maduro"],
  "queso-gouda": ["queso gouda", "gouda maduro", "queso gouda maduro"],
  "queso-panela": ["queso panela", "panela fresco", "queso panela fresco"],
  "queso-cabra": ["queso de cabra", "cabra artesanal", "queso de cabra artesanal"],
  "queso-crema": ["queso crema", "queso crema artesanal"],
  "mantequilla-pastoreo": ["mantequilla", "mantequilla de vaca", "mantequilla de pastoreo", "mantequilla sin sal"],
  "jitomate-bola": ["jitomate", "jitomates", "jitomate bola", "jitomate bola jugoso"],
  "33plus": ["33plus", "33 plus", "fórmula 33plus", "elixir 33plus"],
  "34plus": ["34plus", "34 plus", "fórmula 34plus", "tisana 34plus"]
};

function normalizeToCanonicalSlug(rawName) {
  if (!rawName) return "";
  const clean = rawName.trim().toLowerCase();
  const cleanNoAcc = stripAccents(clean);

  for (const slug in INGREDIENT_CANONICAL_MAP_JS) {
    const aliases = INGREDIENT_CANONICAL_MAP_JS[slug];
    for (const alias of aliases) {
      const aliasClean = stripAccents(alias.trim().toLowerCase());
      if (aliasClean.includes(cleanNoAcc) || cleanNoAcc.includes(aliasClean)) {
        return slug;
      }
    }
  }

  const sanitized = cleanNoAcc.replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/^-+|-+$/g, '');
  return sanitized || "insumo-general";
}

function parseQuantityInBaseUnit(qty, unitRaw) {
  const num = parseFloat(qty) || 0;
  const unitStr = (unitRaw || "").toLowerCase().trim();

  if (unitStr.includes("kg") || unitStr.includes("kilo")) {
    const val = num < 50 ? num * 1000 : num;
    return { val: val, type: "mass", baseUnit: "g" };
  }
  if (unitStr.includes("g") || unitStr.includes("gramo")) {
    return { val: num, type: "mass", baseUnit: "g" };
  }
  if (unitStr.includes("l") || unitStr.includes("litro") || unitStr.includes("lt")) {
    const val = num < 50 ? num * 1000 : num;
    return { val: val, type: "vol", baseUnit: "ml" };
  }
  if (unitStr.includes("ml") || unitStr.includes("mililitro")) {
    return { val: num, type: "vol", baseUnit: "ml" };
  }
  return { val: num, type: "count", baseUnit: unitStr || "piezas" };
}

function getYieldFactor(category, slug) {
  if (category && category.includes("Carnes")) return 1.15;
  if (category && category.includes("Verduras")) return 1.10;
  return 1.00;
}

function formatBaseQuantity(val, type, origUnit) {
  const roundedVal = Math.round(val * 10) / 10;
  if (type === "mass") {
    if (val >= 1000) return `${(val / 1000).toFixed(1)} kg`;
    return `${roundedVal} g`;
  }
  if (type === "vol") {
    if (val >= 1000) return `${(val / 1000).toFixed(1)} L`;
    return `${roundedVal} ml`;
  }
  return `${Math.ceil(val)} ${origUnit || 'piezas'}`;
}

function sanitizeMarketRawMaterial(rawName) {
  if (!rawName) return '';
  let clean = rawName
    .replace(/\s*\(\s*\d+°C\s*\)/gi, '')
    .replace(/\s*\d+°C/gi, '')
    .replace(/\s+fr[íi]a\s+para\s+hidratar/gi, '')
    .replace(/\s+para\s+hidratar/gi, '')
    .replace(/\s+para\s+pochado/gi, '')
    .replace(/\s+para\s+cocci[oó]n/gi, '')
    .replace(/\s+en\s+l[aá]minas(\s+finas)?/gi, '')
    .replace(/\s+en\s+cubos/gi, '')
    .replace(/\s+en\s+guacamole/gi, '')
    .replace(/\s+en\s+bastones/gi, '')
    .replace(/\s+trocead[oa]s?/gi, '')
    .replace(/\s+picad[oa]s?/gi, '')
    .replace(/\s+rostizad[oa]s?/gi, '')
    .replace(/\s+saltead[oa]s?/gi, '')
    .replace(/\s+en\s+tiras/gi, '')
    .replace(/\s+desmenuzad[oa]s?/gi, '')
    .trim();

  const lower = clean.toLowerCase();
  if (lower.includes('portobello') || lower.includes('champiñon') || lower.includes('champiñones') || lower.includes('champinon') || lower.includes('champinones') || lower.includes('setas') || lower.includes('hongos')) return 'Champiñones Portobello frescos';
  if (lower.includes('jitomate') || (lower.includes('tomate') && !lower.includes('tomillo'))) return 'Jitomate bola fresco';
  if (lower.includes('aguacate')) return 'Aguacate Hass fresco';

  // Disolver disyunciones culinarias de lácteos hacia SKUs canónicos deterministas
  if (lower.includes('parmesano o de cabra') || (lower.includes('parmesano') && !lower.includes('nube'))) return 'Queso Parmesano artesanal';
  if (lower.includes('queso de cabra') || lower.includes('cabra artesanal')) return 'Queso de cabra artesanal';
  if (lower.includes('gouda')) return 'Queso Gouda artesanal';
  if (lower.includes('queso crema') || lower.includes('crema suave')) return 'Queso crema suave artesanal';
  if (lower.includes('panela')) return 'Queso Panela artesanal';

  if (lower.includes('pepino')) return 'Pepino blanco fresco';
  if (lower.includes('apio')) return 'Apio fresco de la granja';
  if (lower.includes('zucchini')) return 'Calabacita Zucchini';
  if (lower.includes('calabacita')) return 'Calabacitas tiernas';
  if (lower.includes('hinojo')) return 'Hinojo fresco';
  if (lower.includes('chayote')) return 'Chayotes tiernos de la granja';
  if (lower.includes('esparragos') || lower.includes('espárragos')) return 'Espárragos verdes frescos de la granja';
  if (lower.includes('cilantro')) return 'Cilantro fresco de la granja';
  if (lower.includes('cebollín') || lower.includes('cebollin')) return 'Cebollín fresco de la granja';
  if (lower === 'agua' || lower.includes('agua purificada')) return 'Agua purificada';
  return clean;
}

function processMarketItem(rawName, totalQty, unit) {
  if (!rawName) return [];

  let cleanStr = rawName
    .replace(/\s*\(\s*\d+°C\s*\)/gi, '')
    .replace(/\s*\d+°C/gi, '')
    .replace(/\s+fr[íi]a\s+para\s+hidratar/gi, '')
    .replace(/\s+para\s+hidratar/gi, '')
    .replace(/\s+para\s+pochado/gi, '')
    .replace(/\s+para\s+cocci[oó]n/gi, '')
    .trim();

  const lower = cleanStr.toLowerCase();

  if (lower.includes('jitomate') && lower.includes('cebolla')) {
    return [
      { name: 'Jitomate bola fresco', qty: totalQty * 0.6, unit: 'g' },
      { name: 'Cebolla morada fresca', qty: totalQty * 0.4, unit: 'g' }
    ];
  }
  if (lower.includes('sal de mar') && lower.includes('tomillo')) {
    return [
      { name: 'Sal de mar mineral en escamas', qty: totalQty * 0.7, unit: 'g' },
      { name: 'Tomillo fresco', qty: totalQty * 0.3, unit: 'g' }
    ];
  }
  if (lower.includes('sal de mar') && lower.includes('pimienta')) {
    return [
      { name: 'Sal de mar mineral en escamas', qty: totalQty * 0.7, unit: 'g' },
      { name: 'Pimienta negra molida', qty: totalQty * 0.3, unit: 'g' }
    ];
  }
  if (lower.includes('cilantro') && lower.includes('orégano')) {
    return [
      { name: 'Cilantro fresco de la granja', qty: totalQty * 0.6, unit: 'g' },
      { name: 'Orégano seco', qty: totalQty * 0.4, unit: 'g' }
    ];
  }

  if (/\s+y\s+/i.test(cleanStr) && !lower.includes('aceite') && !lower.includes('mantequilla') && !lower.includes('salmón') && !lower.includes('salmon')) {
    const parts = cleanStr.split(/\s+y\s+/i);
    const subQty = totalQty / parts.length;
    return parts.map(p => ({
      name: sanitizeMarketRawMaterial(p),
      qty: subQty,
      unit: unit
    }));
  }

  const sanitized = sanitizeMarketRawMaterial(rawName);
  return [{ name: sanitized, qty: totalQty, unit: unit }];
}

function calculateActiveMenuBOM(weekKey, diners) {
  const numDiners = parseInt(diners) || (typeof activeDiners !== 'undefined' ? parseInt(activeDiners) || 6 : 6);

  if (weekKey && weekKey.includes("38") && typeof ACTIVE_WEEK_CANONICAL_BOM !== 'undefined' && ACTIVE_WEEK_CANONICAL_BOM && ACTIVE_WEEK_CANONICAL_BOM.bom) {
    const canonicalItems = [];
    for (const catKey in ACTIVE_WEEK_CANONICAL_BOM.bom) {
      const group = ACTIVE_WEEK_CANONICAL_BOM.bom[catKey];
      if (Array.isArray(group)) {
        group.forEach(item => {
          const perPersonQty = item.qty_1 !== undefined ? item.qty_1 : ((item.qty_6 || 0) / 6.0);
          const cleanCat = item.category ? item.category.replace(/\s*\/\s*/g, ' — ').replace(/\//g, ' — ') : '🛒 Abarrotes y Frescos';
          canonicalItems.push({
            id: `bought_v36_${item.canonical_id}`,
            slug: item.canonical_id,
            item_name: item.name,
            category: cleanCat,
            quantity: perPersonQty * numDiners,
            unit: item.unit || 'g',
            is_farm: !!item.is_farm
          });
        });
      }
    }
    if (canonicalItems.length > 0) {
      return canonicalItems;
    }
  }

  const activePlan = getPlanForWeek(weekKey || (typeof activeWeek !== 'undefined' ? activeWeek : 'Semana 40'));
  if (!activePlan || !activePlan.days) return [];

  const bomMap = {};

  activePlan.days.forEach((day, dayIdx) => {
    (day.meals || []).forEach(rawMeal => {
      const activeMeal = typeof getMealObj === 'function' ? getMealObj(dayIdx, rawMeal) : rawMeal;
      const mealDiners = typeof getMealDiners === 'function' ? getMealDiners(dayIdx, activeMeal.meal_type) : numDiners;

      const sRecipe = activeMeal.starter_recipe || (typeof getDishRecipeFromPool === 'function' ? getDishRecipeFromPool(activeMeal.starter_name, 'starter', activeMeal.meal_type) : null);
      const mRecipe = activeMeal.main_recipe || (typeof getDishRecipeFromPool === 'function' ? getDishRecipeFromPool(activeMeal.main_dish_name || activeMeal.dish_name, 'main', activeMeal.meal_type) : null);
      const sdRecipe = activeMeal.side_recipe || (typeof getDishRecipeFromPool === 'function' ? getDishRecipeFromPool(activeMeal.side_dish_name, 'side', activeMeal.meal_type) : null);

      [sRecipe, mRecipe, sdRecipe].forEach(recipe => {
        if (recipe && Array.isArray(recipe.ingredient_groups)) {
          recipe.ingredient_groups.forEach(grp => {
            (grp.items || grp.ingredients || []).forEach(ing => {
              const rawName = ing.name || ing.item_name || '';
              if (!rawName) return;

              const cleanLower = rawName.toLowerCase();
              if (/quinoa|cereza|leche de vaca|azúcar|azucar|miel|durazno/i.test(cleanLower)) {
                return;
              }

              const perPersonQty = parseFloat(ing.base_qty_per_person !== undefined ? ing.base_qty_per_person : (ing.quantity || ing.qty || 1)) || 0;
              const mealQty = perPersonQty * mealDiners;
              const ingUnit = (ing.unit || 'g').trim();

              const processedItems = processMarketItem(rawName, mealQty, ingUnit);

              processedItems.forEach(itemObj => {
                const canonicalName = itemObj.name;
                const slug = normalizeToCanonicalSlug(canonicalName);
                if (!slug) return;

                const itemQty = itemObj.qty;
                const itemUnit = itemObj.unit;

                if (canonicalName === 'Aguacate Hass fresco') {
                  let pieces = 0;
                  if (itemUnit === 'piezas' || itemUnit === 'pz' || itemUnit === 'pieza') {
                    pieces = itemQty;
                  } else if (itemUnit === 'g') {
                    pieces = itemQty / 105.0;
                  } else {
                    pieces = itemQty;
                  }

                  if (!bomMap[slug]) {
                    bomMap[slug] = {
                      id: `bought_v36_${slug}`,
                      slug: slug,
                      item_name: canonicalName,
                      category: getSmartItemCategory(canonicalName, grp.category),
                      quantity: pieces,
                      unit: 'piezas'
                    };
                  } else {
                    bomMap[slug].quantity += pieces;
                  }
                } else {
                  if (!bomMap[slug]) {
                    bomMap[slug] = {
                      id: `bought_v36_${slug}`,
                      slug: slug,
                      item_name: canonicalName,
                      category: getSmartItemCategory(canonicalName, grp.category),
                      quantity: itemQty,
                      unit: itemUnit
                    };
                  } else {
                    bomMap[slug].quantity += itemQty;
                  }
                }
              });
            });
          });
        }
      });
    });
  });

  const resultList = Object.values(bomMap);
  resultList.forEach(item => {
    if (item.unit === 'piezas' || item.unit === 'pz' || item.unit === 'pieza') {
      item.quantity = Math.ceil(item.quantity);
    }
  });

  return resultList;
}

function calculateNetShoppingList(diners) {
  const numDiners = parseInt(diners) || (typeof activeDiners !== 'undefined' ? parseInt(activeDiners) || 6 : 6);
  const factor = numDiners / 6.0;

  let harvestList = [];
  if (typeof selectedHarvest !== 'undefined' && selectedHarvest !== null) {
    if (Array.isArray(selectedHarvest)) {
      harvestList = selectedHarvest;
    } else if (typeof selectedHarvest === 'object') {
      harvestList = Object.keys(selectedHarvest);
    }
  }

  const shoppingCategories = {};
  const farmItems = [];
  const pantryCoveredItems = [];

  let totalCount = 0;
  let farmCount = 0;
  let pantryFullyCoveredCount = 0;
  let pantryActiveCount = (typeof window.PANTRY_STOCK_INVENTORY !== 'undefined' && window.PANTRY_STOCK_INVENTORY)
    ? Object.keys(window.PANTRY_STOCK_INVENTORY).filter(k => window.PANTRY_STOCK_INVENTORY[k] && window.PANTRY_STOCK_INVENTORY[k].status === 'canonical').length
    : 7;
  let marketNetCount = 0;

  const activeBOMItems = calculateActiveMenuBOM(typeof activeWeek !== 'undefined' ? activeWeek : 'Semana 40', numDiners);
  const isFromActiveBOM = activeBOMItems && activeBOMItems.length > 0;
  const itemsToProcess = isFromActiveBOM
    ? activeBOMItems 
    : (typeof rawShopBase !== 'undefined' && Array.isArray(rawShopBase) ? rawShopBase.filter(i => {
        const cleanLower = (i.item_name || '').toLowerCase();
        return !/quinoa|cereza|leche de vaca|azúcar|azucar|miel|durazno/i.test(cleanLower);
      }) : []);

  itemsToProcess.forEach(item => {
    if (!item || !item.item_name) return;
    const cleanName = item.item_name.strip ? item.item_name.strip() : item.item_name;
    const cleanLower = cleanName.toLowerCase();

    if (/quinoa|cereza|leche de vaca|azúcar|azucar|miel|durazno/i.test(cleanLower)) {
      return;
    }

    const slug = normalizeToCanonicalSlug(item.slug || cleanName);
    const catRaw = item.category || getSmartItemCategory(cleanName);
    const cat = catRaw ? catRaw.replace(/\s*\/\s*/g, ' — ').replace(/\//g, ' — ') : '🛒 Abarrotes y Frescos';

    totalCount++;

    const isHarvestInList = harvestList.some(h => {
      if (!h) return false;
      const hStr = typeof h === 'string' ? h : (h.item_name || h.name || '');
      const hSlug = normalizeToCanonicalSlug(hStr);
      const hLower = hStr.toLowerCase();
      return (hSlug && slug && (hSlug === slug || slug.includes(hSlug) || hSlug.includes(slug))) ||
             (hLower && cleanLower && (hLower === cleanLower || cleanLower.includes(hLower) || hLower.includes(cleanLower)));
    });

    const isHarvest = isHarvestInList || cat.includes("Cosecha");

    if (isHarvest) {
      farmCount++;
      farmItems.push({
        name: item.item_name,
        slug: slug,
        reason: "🌿 Cubierto a $0 (Granja El Herami)",
        category: cat
      });
      return;
    }

    const origQty = parseFloat(item.quantity) || 1;
    const grossQty = isFromActiveBOM ? origQty : origQty * factor;
    const yieldFactor = getYieldFactor(cat, slug);
    const grossWithYield = grossQty * yieldFactor;
    const baseInfo = parseQuantityInBaseUnit(grossWithYield, item.unit);

    let stockInBase = 0;
    if (typeof window.PANTRY_STOCK_INVENTORY !== 'undefined' && window.PANTRY_STOCK_INVENTORY) {
      Object.keys(window.PANTRY_STOCK_INVENTORY).forEach(pKey => {
        const pObj = window.PANTRY_STOCK_INVENTORY[pKey];
        if (!pObj || pObj.status !== 'canonical') return;

        const pSlug = normalizeToCanonicalSlug(pObj.name || pKey);
        if (pSlug === slug || pKey === slug || pSlug.includes(slug) || slug.includes(pSlug)) {
          const pQty = parseFloat(pObj.stock) || 0;
          const pUnit = pObj.unit || item.unit;
          stockInBase += parseQuantityInBaseUnit(pQty, pUnit).val;
        }
      });
    }

    const netInBase = Math.max(0, baseInfo.val - stockInBase);

    if (netInBase <= 0) {
      pantryFullyCoveredCount++;
      pantryCoveredItems.push({
        name: item.item_name,
        slug: slug,
        reason: `🧀 Cubierto por Alacena (${formatBaseQuantity(stockInBase, baseInfo.type, item.unit)} disponibles)`,
        category: cat
      });
    } else {
      marketNetCount++;
      const netStr = formatBaseQuantity(netInBase, baseInfo.type, item.unit);
      const grossStr = formatBaseQuantity(baseInfo.val, baseInfo.type, item.unit);
      const pantryStr = formatBaseQuantity(stockInBase, baseInfo.type, item.unit);

      let note = "";
      if (slug === '33plus' || slug === '34plus') {
        note = "(Lote Interno Granja — Laboratorio $0 Mercado)";
      } else if (stockInBase > 0) {
        note = `(Bruto: ${grossStr} | Alacena: ${pantryStr})`;
      }

      if (!shoppingCategories[cat]) shoppingCategories[cat] = [];
      shoppingCategories[cat].push({
        id: `bought_v36_${slug}`,
        slug: slug,
        name: item.item_name,
        qtyStr: netStr,
        grossStr: grossStr,
        pantryStr: pantryStr,
        stockInBase: stockInBase,
        note: note
      });
    }
  });

  return {
    categories: shoppingCategories,
    farmItems: farmItems,
    pantryCoveredItems: pantryCoveredItems,
    totalCount: totalCount,
    farmCount: farmCount,
    pantryFullyCoveredCount: pantryFullyCoveredCount,
    pantryActiveCount: pantryActiveCount,
    marketNetCount: marketNetCount
  };
}

