      modal.className = 'fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4';
      
      const plan = getPlanForWeek(activeWeek);
      const dayName = (plan && plan.days && plan.days[dayIdx]) ? plan.days[dayIdx].day : '';
      const diners = getMealDiners(dayIdx, mealType);

      let rowsHtml = '';
